from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urlsplit
import hashlib,json,re
root=Path('products/services/fixed-prize-data-delivery')
source=root/'raw/topcoder-public-challenges.html'
raw=source.read_bytes()
class Index(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links=set()
        self.scripts=0
        self.parts=[]
        self.hidden=0
    def handle_starttag(self,tag,attrs):
        fields=dict(attrs)
        if tag in ('script','style'):
            self.hidden+=1
            self.scripts+=int(tag=='script')
        href=fields.get('href') or ''
        try:
            url=urlsplit(href)
        except ValueError:
            return
        if tag=='a' and url.scheme in ('','https') and url.netloc.lower() in ('','www.topcoder.com','topcoder.com','api.topcoder.com') and re.search(r'/challenges?/',url.path,re.I):
            self.links.add((f'https://{url.netloc}' if url.netloc else '')+url.path)
    def handle_endtag(self,tag):
        if tag in ('script','style'):
            self.hidden=max(0,self.hidden-1)
    def handle_data(self,data):
        if not self.hidden and data.strip():
            self.parts.append(' '.join(data.split()))
p=Index()
p.feed(raw.decode('utf-8',errors='replace'))
hits=[s[:240] for s in p.parts if re.search(r'prize|deadline|no challenges|active challenges|registration closes',s,re.I)]
result={'capture':'TASK-179547122601','source_sha256':hashlib.sha256(raw).hexdigest(),'challenge_link_count':len(p.links),'challenge_link_pointers':sorted(p.links)[:25],'visible_phrase_count':len(hits),'visible_phrase_pointers':hits[:20],'script_tag_count':p.scripts,'scope':'Static HTML only. A link is a lead. Missing static listings cannot establish the absence of active challenges.'}
(root/'static-index-evidence.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({key:result[key] for key in ('source_sha256','challenge_link_count','visible_phrase_count','script_tag_count')}))
